import test from 'node:test';
import assert from 'node:assert/strict';
import{createHash}from'node:crypto';
import {createRun,strike,frontier,blastArea,canMine,cashOut,rating,validRun,TYPES,LESSONS,cacheRoute,repairRun,upgradeRun,MIN_RANDOM_ENERGY,EXPLORATION_ALLOWANCE}from'../core.mjs';
function plain(rows,budget=10){const r=createRun();r.grid=rows.map(x=>[...x].map(t=>({d:'dirt',s:'stone',T:'tnt',D:'diamond',X:'bedrock',g:'gold',C:'cache','.':null}[t])));r.hits=r.grid.map(x=>x.map(()=>0));r.energy=r.maxEnergy=budget;return r;}
test('only surface and connected openings expose blocks',()=>{const r=plain(['ddddddd','ddddddd','ddddddd']);assert.equal(canMine(r,1,3),false);const before=JSON.stringify(r);assert.equal(strike(r,1,3).ok,false);assert.equal(JSON.stringify(r),before);strike(r,0,3);assert.equal(canMine(r,1,3),true);assert.equal(canMine(r,1,4),false);});
test('disconnected empty cavities are not a back door',()=>{const r=plain(['ddddddd','dd.dddd','ddddddd']);assert.equal(frontier(r).has('2,2'),false);});
test('hardness takes actual hits, while every accepted strike costs one',()=>{const r=plain(['sssDddd','ddddddd']);strike(r,0,3);assert.equal(r.grid[0][3],'diamond');assert.equal(r.hits[0][3],1);strike(r,0,3);strike(r,0,3);assert.equal(r.grid[0][3],null);assert.equal(r.loot.diamond,1);assert.equal(r.score,100);assert.equal(r.energy,7);});
test('TNT breaks a 3x3 area, chains diagonally, collects once and leaves bedrock',()=>{const r=plain(['dddTddd','ddXTgdd','dddDDdd']);const result=strike(r,0,3);assert.equal(result.chain,2);assert.equal(r.energy,9);assert.equal(r.grid[1][2],'bedrock');assert.equal(r.loot.diamond,2);assert.equal(r.loot.gold,1);assert.equal(r.score,235);assert.equal(r.blasts,2);const count=result.events.filter(e=>e.kind==='break');assert.equal(new Set(count.map(e=>`${e.r},${e.c}`)).size,count.length);});
test('last durability resolves chain loot before deciding victory',()=>{const r=plain(['dddTddd','ddDgDdd'],1);const result=strike(r,0,3);assert.equal(result.ok,true);assert.equal(r.energy,0);assert.equal(r.score,235);assert.equal(r.status,'won');});
test('last durability on a partial hit ends cleanly and cannot be spent again',()=>{const r=plain(['sssssss','ddddddd'],1);strike(r,0,3);assert.equal(r.status,'exhausted');const before=JSON.stringify(r);assert.equal(strike(r,0,3).ok,false);assert.equal(JSON.stringify(r),before);});
test('bedrock is neither mineable nor affected by explosions',()=>{const r=plain(['XXXTXdd','XXXXXXX']);assert.equal(strike(r,0,1).ok,false);strike(r,0,3);assert.equal(r.grid[0][2],'bedrock');assert.equal(r.grid[1][3],'bedrock');});
test('cash out settles once and disables all further mining',()=>{const r=createRun('random',0,5);strike(r,0,3);cashOut(r);assert.equal(r.status,'banked');assert.equal(strike(r,0,3).ok,false);cashOut(r);assert.equal(r.status,'banked');});
test('retrying a seed restores its exact map and clean counters',()=>{const a=createRun('random',0,987),b=createRun('random',0,987);assert.deepEqual(a,b);strike(a,0,3);assert.notDeepEqual(a,b);assert.deepEqual(createRun('random',0,987),b);assert.notDeepEqual(b.grid,createRun('random',0,988).grid);});
test('snapshots round-trip and reject malformed layout',()=>{const r=createRun();strike(r,0,3);const saved=JSON.parse(JSON.stringify(r));assert.equal(validRun(saved),true);saved.grid[0][0]='nonsense';assert.equal(validRun(saved),false);assert.equal(validRun(null),false);});
test('blast range clips correctly on mine boundaries',()=>{const r=createRun();assert.equal(blastArea(r,0,0).length,4);assert.equal(blastArea(r,3,3).length,9);});

// Dijkstra on the actual map: aim at useful TNT, not merely the deepest block.
export function plan(run){const steps=[];for(let iter=0;iter<100&&run.status==='active';iter++){
  const distance=new Map(),prev=new Map(),q=[];for(const key of frontier(run)){const [r,c]=key.split(',').map(Number),t=run.grid[r][c];distance.set(key,TYPES[t].hp-run.hits[r][c]);q.push(key);}
  while(q.length){q.sort((a,b)=>distance.get(a)-distance.get(b));const key=q.shift(),[r,c]=key.split(',').map(Number);for(const [y,x]of[[r-1,c],[r+1,c],[r,c-1],[r,c+1]]){if(y<0||y>=run.grid.length||x<0||x>=7)continue;const t=run.grid[y][x];if(!t||t==='bedrock')continue;const nk=`${y},${x}`,d=distance.get(key)+TYPES[t].hp-run.hits[y][x];if(d<(distance.get(nk)??Infinity)){distance.set(nk,d);prev.set(nk,key);q.push(nk);}}}
  let candidates=[...distance].map(([key,cost])=>{const [r,c]=key.split(',').map(Number),t=run.grid[r][c];let weight=t==='tnt'?12:t==='cache'?24:t==='diamond'?4:t==='gold'?1:0;
    if(run.mode==='lesson'&&run.index===1&&t==='diamond')weight+=5;
    if(run.mode==='random'||run.index===2)weight*=1+r/run.grid.length*1.8;
    return{key,priority:weight/cost};}).sort((a,b)=>b.priority-a.priority);
  if(!candidates.length)break;let key=candidates[0].key;while(prev.has(key))key=prev.get(key);const [r,c]=key.split(',').map(Number);const result=strike(run,r,c);if(!result.ok)throw Error('planner invalid step');steps.push([r,c]);
}return steps;}
test('all three teaching maps have achievable goals within their budgets',()=>{for(let i=0;i<3;i++){const r=createRun('lesson',i);const steps=plan(r);assert.equal(r.status,'won',`lesson ${i+1}, ${steps.length} strikes, score ${r.score}, depth ${r.depth}`);assert.ok(rating(r)>=1);}});
test('legacy 42-hit precision routes still complete the original 100 test seeds',()=>{for(let seed=1;seed<=100;seed++){const r=createRun('random',0,seed);r.balanceVersion=2;r.energy=r.maxEnergy=42;plan(r);assert.equal(r.status,'won',`seed ${seed}, score ${r.score}, depth ${r.depth}`);}});

function replayRoute(run,route){for(const[r,c]of route.path)while(run.grid[r][c]&&run.status==='active'){assert.equal(strike(run,r,c).ok,true,`${run.seed}: legal route at ${r},${c}`);}return run;}
test('1000 generated maps include a verified route plus exploration allowance',()=>{for(let seed=0;seed<1000;seed++){const r=createRun('random',0,seed),route=cacheRoute(r);assert.ok(Number.isFinite(route.cost));assert.ok(r.maxEnergy>=MIN_RANDOM_ENERGY);assert.ok(r.maxEnergy-route.cost>=EXPLORATION_ALLOWANCE);assert.equal(replayRoute(r,route).status,'won');}});
test('route hint identifies a reachable next block without mutating the run',()=>{const r=createRun('random',0,999),before=JSON.stringify(r),route=cacheRoute(r);assert.deepEqual(r,JSON.parse(before));assert.ok(frontier(r).has(route.next.join(',')));strike(r,...route.next);const next=cacheRoute(r);assert.ok(next.cost<=route.cost);assert.ok(frontier(r).has(next.next.join(',')));});
test('free repair retains the exact mine, loot, score, depth and spent strikes',()=>{const r=createRun('random',0,1);for(let i=0;i<5;i++)strike(r,...cacheRoute(r).next);r.energy=0;r.status='exhausted';const before=structuredClone(r),cost=cacheRoute(r).cost,result=repairRun(r);assert.equal(result.ok,true);assert.ok(r.energy>=cost+12);assert.ok(r.energy>=24);assert.equal(r.status,'active');assert.equal(r.repairCount,1);for(const key of['grid','hits','score','loot','strikes','depth','seed','maxEnergy'])assert.deepEqual(r[key],before[key]);assert.equal(repairRun(r).ok,false);assert.equal(replayRoute(r,cacheRoute(r)).status,'won');assert.equal(repairRun(r).ok,false);});
test('a player can repair again after another exhausted attempt',()=>{const r=createRun('random',0,71);for(let i=1;i<=3;i++){r.energy=0;r.status='exhausted';assert.equal(repairRun(r).ok,true);assert.equal(r.repairCount,i);}assert.equal(replayRoute(r,cacheRoute(r)).status,'won');});
test('legacy 42-hit save migration adds only the budget difference, once',()=>{const r=createRun('random',0,987);strike(r,0,3);delete r.balanceVersion;r.maxEnergy=42;r.energy=41;const before=structuredClone(r),result=upgradeRun(r);assert.equal(result.added,r.maxEnergy-42);assert.equal(r.energy,r.maxEnergy-1);for(const key of['grid','hits','score','loot','strikes','depth','seed'])assert.deepEqual(r[key],before[key]);assert.equal(upgradeRun(r).added,0);assert.equal(r.energy,r.maxEnergy-1);assert.equal(validRun(JSON.parse(JSON.stringify(r))),true);});
test('legacy exhausted random saves recover; teaching and banked runs stay unchanged',()=>{const r=createRun('random',0,23);delete r.balanceVersion;r.maxEnergy=42;r.energy=0;r.status='exhausted';upgradeRun(r);assert.equal(r.status,'active');assert.ok(r.energy>=10);const lesson=createRun(),banked=createRun('random',0,24);cashOut(banked);for(const a of[lesson,banked]){const before=structuredClone(a);assert.equal(upgradeRun(a).added,0);assert.equal(repairRun(a).ok,false);assert.deepEqual(a,before);}});
function supplyMine(){const r=plain(Array.from({length:24},(_,i)=>i===23?'...C...':'...d...'),52);r.mode='random';return r;}
test('depth supplies pay exactly once at 8 and 16 metres and survive snapshots',()=>{let r=supplyMine();for(let row=0;row<17;row++){const result=strike(r,row,3);assert.equal(result.events.filter(e=>e.kind==='supply').length,[7,15].includes(row)?1:0);if(row===7){assert.equal(r.energy,50);assert.equal(r.maxEnergy,58);r=JSON.parse(JSON.stringify(r));}if(row===15){assert.equal(r.energy,48);assert.equal(r.maxEnergy,64);}}assert.deepEqual(r.depthBonuses,[8,16]);assert.equal(r.energy,47);r.status='exhausted';r.energy=0;repairRun(r);assert.deepEqual(r.depthBonuses,[8,16]);assert.equal(strike(r,17,3).events.some(e=>e.kind==='supply'),false);});
test('the last available hit earns its depth supply before exhaustion is evaluated',()=>{const r=supplyMine();for(let row=0;row<7;row++)strike(r,row,3);r.energy=1;const result=strike(r,7,3);assert.equal(r.energy,6);assert.equal(r.status,'active');assert.equal(result.events.at(-1).kind,'supply');});
test('one TNT chain can cross both supply milestones without double payouts',()=>{const r=supplyMine();for(let row=0;row<16;row++)r.grid[row][3]='tnt';const result=strike(r,0,3);assert.equal(result.chain,16);assert.deepEqual(result.events.filter(e=>e.kind==='supply').map(e=>e.depth),[8,16]);assert.equal(r.energy,63);assert.equal(r.maxEnergy,64);assert.equal(strike(r,17,3).events.some(e=>e.kind==='supply'),false);});
test('teaching maps keep their original budgets and have no depth supplies',()=>{for(let i=0;i<3;i++){const r=createRun('lesson',i);plan(r);assert.equal(r.maxEnergy,LESSONS[i].budget);assert.deepEqual(r.depthBonuses,[]);}});
test('unstarted 80-hit saves adopt the new budget; started saves keep every remaining hit',()=>{for(const spent of[0,3]){const r=createRun('random',0,14);r.balanceVersion=2;r.energy=80-spent;r.maxEnergy=80;r.strikes=spent;const before=structuredClone(r);upgradeRun(r);assert.equal(r.energy,spent?77:52);assert.equal(r.maxEnergy,spent?80:52);assert.deepEqual(r.depthBonuses,spent?[8,16]:[]);for(const key of['grid','hits','score','loot','strikes','depth','seed'])assert.deepEqual(r[key],before[key]);const migrated=structuredClone(r);upgradeRun(r);assert.deepEqual(r,migrated);}});
test('balance changes preserve the existing seeded maps exactly',()=>{const cases={0:'09ee01e8a88a21a88a44185dd51814ca183c2eb098b8230da4c166fbc798c8b5',1:'8061a562022d2490e898986c2b859431892109a90a3e283e43820f5bfd9bd1bc',987:'68580a6b59c337c1bfd3986fd4b9a48f9e6016a76d22287596c9b4b548ce6d9b',4294967295:'ac3eeed931af6fd2f64e1aa1ce661391073f719c384af0bc01aa8e89cd5e990d'};for(const[seed,hash]of Object.entries(cases))assert.equal(createHash('sha256').update(JSON.stringify(createRun('random',0,Number(seed)).grid)).digest('hex'),hash);});
